import{_ as a,o as l,c as r,ag as e}from"./chunks/framework.CtWPcAmt.js";const c=JSON.parse('{"title":"第 9 章：跟进过程，而不是只等最终答案","description":"何时让 Agent 自主推进、何时分段确认、如何处理中断/追问/偏航/失败；产出任务过程检查清单。","frontmatter":{"title":"第 9 章：跟进过程，而不是只等最终答案","description":"何时让 Agent 自主推进、何时分段确认、如何处理中断/追问/偏航/失败；产出任务过程检查清单。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/09-follow-progress.md","filePath":"guide/09-follow-progress.md","lastUpdated":null}'),i={name:"guide/09-follow-progress.md"};function o(d,t,n,h,s,g){return l(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="第-9-章-跟进过程-而不是只等最终答案" tabindex="-1">第 9 章：跟进过程，而不是只等最终答案 <a class="header-anchor" href="#第-9-章-跟进过程-而不是只等最终答案" aria-label="Permalink to &quot;第 9 章：跟进过程，而不是只等最终答案&quot;">​</a></h1><h2 id="本章解决什么问题" tabindex="-1">本章解决什么问题 <a class="header-anchor" href="#本章解决什么问题" aria-label="Permalink to &quot;本章解决什么问题&quot;">​</a></h2><p>很多新手把任务发给 Agent 后做两件事之一：要么一直刷新等最终答案，要么全程紧张盯屏。两种都错。正确的做法是<strong>按风险分阶段监督</strong>：知道什么时候该放手、什么时候该叫停、什么时候该插话。本章产出<strong>任务过程检查清单</strong>，并教你读懂执行过程里真正值得关注的信息。</p><h2 id="从一个真实场景开始" tabindex="-1">从一个真实场景开始 <a class="header-anchor" href="#从一个真实场景开始" aria-label="Permalink to &quot;从一个真实场景开始&quot;">​</a></h2><p>我在第 5 章实测里让七款产品做同一个任务，全程观察它们的执行过程：</p><ul><li>有的产品把 6 份文件在几秒内一口气写完（快，但你看不见过程）；</li><li>有的产品一份一份写，你能在文件系统里看到进度（WorkBuddy、TraeWork 等）；</li><li>有一款产品的自检在任务「完成后」又修改了一个文件（Codex 的后置修订）；</li><li>有一款产品中途把文件写错位置，自己恢复（Hermes）。</li></ul><p><strong>如果你只盯最终答案，以上任何一条你都发现不了。</strong> 而「任务是否真的完成、过程是否合规」，恰恰要从过程信息里判断。</p><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><ol><li><strong>监督强度 = 风险函数</strong>（呼应第 2 章 L1–L4）：低风险放手跑，高风险分段停；</li><li><strong>三种节奏按需切换</strong>：全自动（跑完汇报）、分段确认（每段停一次）、实时接管（高风险/不熟悉任务）；</li><li><strong>过程里真正值得看的四类信息</strong>：它在做什么、它遇到了什么问题、它怎么解决的、它有没有越出边界；</li><li><strong>处理四种情况有固定套路</strong>：中断→续跑或重跑；追问→补信息；偏航→纠偏并说明；失败→记录原因后重试；</li><li><strong>「Agent 说完成了」是过程信号，不是验收结论</strong>——验收是第 10 章的事，这里只管「别让它失控」。</li></ol><h2 id="必要概念" tabindex="-1">必要概念 <a class="header-anchor" href="#必要概念" aria-label="Permalink to &quot;必要概念&quot;">​</a></h2><ul><li><strong>分段确认（Checkpoint）</strong>：在任务的关键节点暂停，由人确认后再继续。白话解释：装修每做完一阶段，业主验收再进下一阶段。</li><li><strong>偏航（Drift）</strong>：Agent 的执行偏离了任务目标或约束。白话解释：让它总结 A 材料，它开始扩展成写论文。</li><li><strong>过程日志（Log）</strong>：Agent 执行动作的记录（读了什么、写了什么、调用了什么）。多数产品有「变更/历史/操作统计」视图（第 5 章各产品页有对照）。</li><li><strong>接管（Takeover）</strong>：人直接介入纠正 Agent 的当前动作。不要怕接管——及时接管比事后返工便宜。</li></ul><h2 id="任务过程检查清单" tabindex="-1">任务过程检查清单 <a class="header-anchor" href="#任务过程检查清单" aria-label="Permalink to &quot;任务过程检查清单&quot;">​</a></h2><p><strong>发任务前</strong>（30 秒）：</p><ul><li>[ ] 任务卡六要素齐全（第 7 章）；</li><li>[ ] 权限卡已设置、输出目录已建（第 8 章）；</li><li>[ ] 我已决定监督档位（自动 / 分段 / 接管）。</li></ul><p><strong>执行中</strong>（按档位检查）：</p><ul><li>[ ] Agent 是否在按任务卡的目标推进？（不看细节，看方向）</li><li>[ ] 是否出现了我没授权过的动作？（读/写/联网越界）</li><li>[ ] 是否卡在同一个问题上反复重试？（&gt;2 次应插话）</li><li>[ ] 分段确认点是否到了？到了就停下来验收这一段。</li></ul><p><strong>执行后</strong>（交付前）：</p><ul><li>[ ] 有没有「后置修改」（它完成后又动了文件）？改了哪、为什么？</li><li>[ ] 过程日志里有没有越界读写记录？</li><li>[ ] 有没有把「推测」当成「事实」写进结果？</li><li>[ ] 交付清单与实际产物是否一致（防止遗漏）？</li></ul><h2 id="跟着做-跑一次「带监督」的任务" tabindex="-1">跟着做：跑一次「带监督」的任务 <a class="header-anchor" href="#跟着做-跑一次「带监督」的任务" aria-label="Permalink to &quot;跟着做：跑一次「带监督」的任务&quot;">​</a></h2><h3 id="第一步-定档位" tabindex="-1">第一步：定档位 <a class="header-anchor" href="#第一步-定档位" aria-label="Permalink to &quot;第一步：定档位&quot;">​</a></h3><p>对序章任务，按第 2 章等级定档：L1 全自动、L2 分段、L3/L4 实时接管。</p><h3 id="第二步-设分段确认点" tabindex="-1">第二步：设分段确认点 <a class="header-anchor" href="#第二步-设分段确认点" aria-label="Permalink to &quot;第二步：设分段确认点&quot;">​</a></h3><p>如果 L2，明确在哪几处停：通常在「材料读完 → 计划出来」「每完成 1/3 交付物」「自检完成」时。</p><h3 id="第三步-执行并记录" tabindex="-1">第三步：执行并记录 <a class="header-anchor" href="#第三步-执行并记录" aria-label="Permalink to &quot;第三步：执行并记录&quot;">​</a></h3><p>用「过程记录表」记下：时间、Agent 在做什么、你做了什么决定：</p><table tabindex="0"><thead><tr><th>时间</th><th>Agent 动作</th><th>你观察到什么</th><th>你的决定</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td></tr></tbody></table><h3 id="第四步-对照检查清单收尾" tabindex="-1">第四步：对照检查清单收尾 <a class="header-anchor" href="#第四步-对照检查清单收尾" aria-label="Permalink to &quot;第四步：对照检查清单收尾&quot;">​</a></h3><p>交付前过一遍「执行后」的四项检查，把异常写进记录，留到第 10 章验收。</p><h2 id="一个完整示例" tabindex="-1">一个完整示例 <a class="header-anchor" href="#一个完整示例" aria-label="Permalink to &quot;一个完整示例&quot;">​</a></h2><p>我实测 Codex 时的过程观察（详见第 5 章 Codex 页）：</p><ul><li>任务：统一基准（材料整理，L1 低风险）→ 监督档位设为「全自动 + 交付后检查」；</li><li>执行：6 份文件几乎同时写入 → 视为正常；</li><li><strong>异常信号</strong>：约 1 分钟后 <code>02-information-gaps.md</code> 被再次修改（后置修订）——我没有打断，记下「最终版本按后置版本验收」；</li><li>交付后检查：自检覆盖 7 份输入、无越界记录 → 通过；</li><li>结论：全自动档位 + 交付后检查，适用于 L1；<strong>那个后置修订如果不看过程就发现不了</strong>，也就无法决定「按哪个版本验收」。</li></ul><h2 id="常见错误与恢复方法" tabindex="-1">常见错误与恢复方法 <a class="header-anchor" href="#常见错误与恢复方法" aria-label="Permalink to &quot;常见错误与恢复方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎样修正</th></tr></thead><tbody><tr><td>一直刷新等最终答案</td><td>把过程当黑箱</td><td>看「它在做什么」的过程信息；L2+ 设分段确认</td></tr><tr><td>全程盯屏不敢离开</td><td>监督过度</td><td>低风险段设「跑完汇报」，别事无巨细</td></tr><tr><td>Agent 卡住反复重试</td><td>缺信息/指令矛盾</td><td>插话补信息或澄清，别让它空转</td></tr><tr><td>它跑偏了才发现</td><td>没设分段点</td><td>关键节点设确认点</td></tr><tr><td>任务「完成」后又变了文件</td><td>后置修改</td><td>记录并决定验收版本，别只看首次完成时间</td></tr><tr><td>看不懂过程信息</td><td>界面不熟</td><td>用第 5 章各产品页的「过程/变更视图」说明对照学习</td></tr></tbody></table><h2 id="安全提醒" tabindex="-1">安全提醒 <a class="header-anchor" href="#安全提醒" aria-label="Permalink to &quot;安全提醒&quot;">​</a></h2><ul><li>看到<strong>权限弹窗、联网请求、执行命令</strong>时，即使任务快完成了，也要停下来确认——「快跑完了」不是忽略风险的理由；</li><li>Agent 反复重试同一操作时，先怀疑「方向错了」，不要让它无限重试；</li><li>对外动作（发送/发布）即使 Agent 说「已准备好」，也要你亲手完成最后一步。</li></ul><h2 id="本章练习" tabindex="-1">本章练习 <a class="header-anchor" href="#本章练习" aria-label="Permalink to &quot;本章练习&quot;">​</a></h2><p>20 分钟：用「过程记录表」重跑你上一个真实任务（或序章任务），按检查清单过一遍，找出 2 个你以前忽略的过程信号。</p><h2 id="你应该带走的成果" tabindex="-1">你应该带走的成果 <a class="header-anchor" href="#你应该带走的成果" aria-label="Permalink to &quot;你应该带走的成果&quot;">​</a></h2><ul><li><strong>任务过程检查清单</strong>（发前/执行中/交付后三组）+ 过程记录表。</li></ul><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>监督强度随风险变化：自动 / 分段 / 接管三档；</li><li>过程里看四件事：在做什么、遇到什么、怎么解决、有没有越界；</li><li>中断/追问/偏航/失败各有固定处理套路；</li><li>「完成」是过程信号，不是验收结论；</li><li>后置修改、越界读写这些信号，只有跟进过程才看得到。</li></ol>',41)])])}const b=a(i,[["render",o]]);export{c as __pageData,b as default};
